theorem:
/-- This asserts that for any list of field operators φs and Wick contractions φsΛ, φsucΛ, and φsΛ' of appropriate lengths, if φsΛ equals φsΛ', then the join of φsΛ and φsucΛ equals the join of φsΛ' and the Wick contraction formed by applying a congruence transformation based on this equality to φsucΛ.-/
lemma join_congr {φs : List 𝓕.FieldOp} {φsΛ : WickContraction φs.length}
    {φsucΛ : WickContraction [φsΛ]ᵘᶜ.length} {φsΛ' : WickContraction φs.length}
    (h1 : φsΛ = φsΛ') :
    join φsΛ φsucΛ = join φsΛ' (congr (by simp [h1]) φsucΛ) := by sorry

/-- This asserts that for any list of field operators φs, Wick contraction φsΛ of length matching φs, and Wick contraction φsucΛ of length matching the uncomplemented list [φsΛ], the function joinLift with these parameters is injective.-/
lemma joinLift_injective {φs : List 𝓕.FieldOp} {φsΛ : WickContraction φs.length}
    {φsucΛ : WickContraction [φsΛ]ᵘᶜ.length} : Function.Injective (@joinLift _ _ φsΛ φsucΛ) := by sorry

/-- This theorem states that, given a list of field operations φs and corresponding Wick contractions φsΛ and φsucΛ, the function joinLift is surjective.-/
lemma joinLift_surjective {φs : List 𝓕.FieldOp} {φsΛ : WickContraction φs.length}
    {φsucΛ : WickContraction [φsΛ]ᵘᶜ.length} : Function.Surjective (@joinLift _ _ φsΛ φsucΛ) := by sorry

/-- This theorem states that the function `joinLift`, parameterized by Wick contractions `φsΛ` and `φsucΛ` of appropriate lengths, is bijective.-/
lemma joinLift_bijective {φs : List 𝓕.FieldOp} {φsΛ : WickContraction φs.length}
    {φsucΛ : WickContraction [φsΛ]ᵘᶜ.length} : Function.Bijective (@joinLift _ _ φsΛ φsucΛ) := by sorry

natural_question:
Let φs be a list of field operators, let φsΛ be a Wick contraction whose length matches that of φs, and let φsucΛ be a Wick contraction on the uncontracted list associated to φsΛ. For any index i in the uncontracted list of φsΛ, the following are equivalent:
- the dual-operator query on the joined contraction join(φsΛ, φsucΛ), evaluated at the embedding of i into the uncontracted list, returns none;
- the dual-operator query on φsucΛ at index i returns none.

theorem:
/-- This asserts that for a differentiable function on spacetime, the time slice of its partial derivative in the spacetime direction corresponding to the (i+1)th coordinate equals the spatial partial derivative in the ith direction of the time-sliced function.-/
lemma timeSlice_spatial_deriv {M : Type}
    [NormedAddCommGroup M] [NormedSpace ℝ M] {d : ℕ} {f : SpaceTime d → M}
    {t : Time} {x : Space d}
    (hdiff : DifferentiableAt ℝ f (toTimeAndSpace.symm (t, x))) (i : Fin d) :
    timeSlice (∂_ (Fin.natAdd 1 i) f) t x = ∂[i] (timeSlice f t) x := by sorry

/-- This theorem states that, for a function f mapping spacetime to a normed vector space M, if f is differentiable at the spacetime point corresponding to time t and spatial location x, then the time slice of the derivative of f along the time direction equals the partial time derivative of the time slice of f at that point.-/
lemma timeSlice_time_deriv {M : Type}
    [NormedAddCommGroup M] [NormedSpace ℝ M] {d : ℕ} (f : SpaceTime d → M)
    {t : Time} {x : Space d}
    (hdiff : DifferentiableAt ℝ f (toTimeAndSpace.symm (t, x))) :
    timeSlice (∂_ (finSumFinEquiv (Sum.inl 0)) f) t x = ∂ₜ (fun t => timeSlice f t x) t := by sorry

/-- This theorem states that if a function \( f_0 \) from the reals to a \( d \)-dimensional Euclidean space is differentiable, and a function \( f \) from time and space to the same Euclidean space is equal to a plane wave with speed \( c \) and direction \( s \) based on \( f_0 \), then for any fixed spatial point \( x \), the function of time \( t \mapsto f(t, x) \) is differentiable.-/
lemma time_differentiable_of_eq_planewave {s : Direction d}
    {f₀ : ℝ → EuclideanSpace ℝ (Fin d)} {f : Time → Space d → EuclideanSpace ℝ (Fin d)}
    (h' : Differentiable ℝ f₀) (hf : f = planeWave f₀ c s) :
    Differentiable ℝ fun t => f t x := by sorry

/-- This lemma claims that, given a direction vector s, a differentiable function f₀ from real numbers to 3D Euclidean space, and a function f defined as a plane wave with profile f₀, speed c, and direction s, the cross product of s's unit vector with f evaluated at any fixed spatial point x is differentiable with respect to time at every time t.-/
lemma crossProduct_time_differentiable_of_right_eq_planewave {s : Direction}
    {f₀ : ℝ → EuclideanSpace ℝ (Fin 3)} {f : Time → Space → EuclideanSpace ℝ (Fin 3)}
    (h' : Differentiable ℝ f₀) (hf : f = planeWave f₀ c s) :
    DifferentiableAt ℝ (fun t => s.unit ⨯ₑ₃ (f t x)) t := by sorry

/-- This lemma claims that for any element V in the quotient set CKMMatrixSetoid and any index i in Fin 3, if the value of VAbs at index 0 and i for V equals 1, then the value of VAbs at index 1 and i for V must equal 0.-/
lemma VAbs_fst_col_eq_one_snd_eq_zero {V : Quotient CKMMatrixSetoid} {i : Fin 3}
    (hV : VAbs 0 i V = 1) : VAbs 1 i V = 0 := by sorry

