/-- This lemma claims that for any real-valued matrix A of dimensions 4×4 (indexed by Fin 1 ⊕ Fin 3), if the transpose of A multiplied by η equals the negative of η multiplied by A, then A is an element of the Lorentz algebra.-/
lemma mem_of_transpose_eta_eq_eta_mul_self {A : Matrix (Fin 1 ⊕ Fin 3) (Fin 1 ⊕ Fin 3) ℝ}
    (h : Aᵀ * η = - η * A) : A ∈ lorentzAlgebra := by sorry

/-- This asserts that for any list of field operators φs, any Wick contraction structure φsΛ of corresponding length, and any finite subset a of indices, if a belongs to the equal-time contraction set associated with φsΛ, then a is also contained in the underlying set of Wick contractions φsΛ.1.-/
lemma mem_of_mem_eqTimeContractSet{φs : List 𝓕.FieldOp} {φsΛ : WickContraction φs.length}
    {a : Finset (Fin φs.length)} (h : a ∈ eqTimeContractSet φsΛ) : a ∈ φsΛ.1 := by sorry

/-- This theorem states that for any list of field operators φs and any Wick contraction φsΛ of corresponding length, if φsΛ contains no equal-time contractions, then its set of equal-time contractions is empty.-/
lemma eqTimeContractSet_of_not_haveEqTime {φs : List 𝓕.FieldOp} {φsΛ : WickContraction φs.length}
    (h : ¬ HaveEqTime φsΛ) : eqTimeContractSet φsΛ = ∅ := by sorry

/-- This theorem states that for any list of field operators φs and any Wick contraction φsΛ of corresponding length, if φsΛ is an equality-time-only contraction, then the equality-time contraction set of φsΛ equals the first projection of φsΛ.-/
lemma eqTimeContractSet_of_mem_eqTimeOnly {φs : List 𝓕.FieldOp} {φsΛ : WickContraction φs.length}
    (h : φsΛ.EqTimeOnly) : eqTimeContractSet φsΛ = φsΛ.1 := by sorry

/-- This lemma claims that for any set \( S \) of linear solutions in the context of \( \text{PureU1}(2 \cdot n + 2) \), if \( S \) satisfies the condition \( \text{LineInCubicPerm} \), then it also satisfies \( \text{LineInPlaneCond} \).-/
lemma lineInCubicPerm_last_perm {S : (PureU1 (2 * n.succ.succ)).LinSols}
    (LIC : LineInCubicPerm S) : LineInPlaneCond S := by sorry

/-- This theorem states that if a functional operator F has a variational adjoint F' with respect to a measure μ, then the operator formed by pointwise negation of F (i.e., -F) also has a variational adjoint, given by the pointwise negation of F' (i.e., -F'), with respect to the same measure μ.-/
lemma neg {F : (X → U) → (X → V)} {F' : (X → V) → (X → U)}
    {μ : Measure X}
    (hF : HasVarAdjoint F F' μ) :
    HasVarAdjoint (fun φ x => - F φ x) (fun φ x => - F' φ x) μ where
  test_fun_preserving _ hφ := by sorry

/-- This lemma claims that, given an operator \( F \) on real-valued functions over \( X \) with a variational adjoint \( F' \) with respect to a measure \( \mu \), and given a smooth function \( \psi \), the operator defined by pointwise multiplication with \( \psi \) composed with \( F \) also has a variational adjoint. Specifically, this adjoint is given by applying \( F' \) to the function formed by pointwise multiplication of \( \psi \) with the input function.-/
lemma mul_left {F : (X → ℝ) → (X → ℝ)} {ψ : X → ℝ} {F' : (X → ℝ) → (X → ℝ)}
    {μ : Measure X}
    (hF : HasVarAdjoint F F' μ) (hψ : ContDiff ℝ ∞ ψ) :
    HasVarAdjoint (fun φ x => ψ x * F φ x) (fun φ x => F' (fun x => ψ x * φ x) x) μ where
  test_fun_preserving φ hφ := by sorry

/-- This theorem states that if F is a functional operator with a variational adjoint F' with respect to measure μ, and ψ is a smooth real-valued function, then the operator defined by pointwise multiplication of F's output by ψ also has a variational adjoint. Specifically, this adjoint is given by applying F' to the function obtained by pointwise multiplying the input by ψ.-/
lemma smul_left {F : (X → U) → (X → V)} {ψ : X → ℝ} {F' : (X → V) → (X → U)}
    {μ : Measure X}
    (hF : HasVarAdjoint F F' μ) (hψ : ContDiff ℝ ∞ ψ) :
    HasVarAdjoint (fun φ x => ψ x • F φ x) (fun φ x => F' (fun x' => ψ x' • φ x') x) μ where
  test_fun_preserving φ hφ := by sorry

/-- This lemma claims that if F is a variational adjoint operator with adjoint F' under measure μ, and ψ is an infinitely differentiable real-valued function, then the operator mapping φ to the pointwise product ψ • F φ also has a variational adjoint. Specifically, this adjoint is given by mapping φ to F' applied to the function x' ↦ ψ x' • φ x'.-/
lemma smul_right {F : (X → U) → (X → V)} {ψ : X → ℝ} {F' : (X → V) → (X → U)}
    {μ : Measure X}
    (hF : HasVarAdjoint F F' μ) (hψ : ContDiff ℝ ∞ ψ) :
    HasVarAdjoint (fun φ x => ψ x • F φ x) (fun φ x => F' (fun x' => ψ x' • φ x') x) μ where
  test_fun_preserving φ hφ := by sorry

/-- This lemma claims that for any solution S in the PureU1 group of odd dimension (2n+1) satisfying the SpecialCase condition, the first projection of S lies in the LineInCubic property.-/
lemma special_case_lineInCubic {S : (PureU1 (2 * n.succ)).Sols}
    (h : SpecialCase S) : LineInCubic S.1.1 := by sorry

